import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const rows = JSON.parse(fs.readFileSync(path.join(root, 'shared/error-codes.json'), 'utf8'));
const name = code => code.toLowerCase().replace(/(^|_)([a-z])/g, (_, a, b) => b.toUpperCase());
const width = Math.max(...rows.map(row => name(row.code).length));
const outputs = {
  'apps/api/pkg/apierror/codes.gen.go': '// Code generated by scripts/generate-error-codes.mjs; DO NOT EDIT.\npackage apierror\n\ntype Code string\n\nconst (\n' + rows.map(r => `\t${name(r.code).padEnd(width + 1)}Code = "${r.code}"`).join('\n') + '\n)\n\ntype Metadata struct {\n\tStatus      int\n\tDescription string\n}\n\nvar Registry = map[Code]Metadata{\n' + rows.map(r => `\t${(name(r.code)+':').padEnd(width + 2)}{${r.status}, ${JSON.stringify(r.error)}},`).join('\n') + '\n}\n',
  'apps/web/src/api/error-codes.gen.ts': '// Generated by scripts/generate-error-codes.mjs; DO NOT EDIT.\nexport const errorCodes = ' + JSON.stringify(rows.map(r => r.code), null, 2) + ' as const;\nexport type ErrorCode = (typeof errorCodes)[number];\n',
};
for (const [file, content] of Object.entries(outputs)) {
  const target = path.join(root, file);
  if (process.argv.includes('--check')) {
    if (!fs.existsSync(target) || fs.readFileSync(target, 'utf8').replaceAll('\r\n', '\n') !== content) throw Error(`Stale generated file: ${file}`);
  } else { fs.mkdirSync(path.dirname(target), { recursive: true }); fs.writeFileSync(target, content); }
}
